"""Explicit capabilities, never a free-form shell generated by a model."""
import os
from pathlib import Path
import re


class TerminalError(ValueError):
    def __init__(self,message,code='terminal_policy'):
        super().__init__(message);self.code=code


REGISTRY=re.compile(r'(?i)(?:\breg(?:edit|edt32)?(?:\.exe)?\b|\bregini\b|\bregsvr32\b|\b(?:hkey_[a-z_]+|hkcu|hklm|hkcr|hku|hkcc)\b|registry::|microsoft\.win32\.registry|\bwinreg\b|\.reg(?:\s|$))')
PROTECTED=re.compile(r'(?i)^(?:reg|regedit|regedt32|regini|regsvr32|diskpart|format|bcdedit|bcdboot|cipher|sdelete|takeown|icacls|netsh|shutdown|rundll32|mshta|wscript|cscript|schtasks|sc)(?:\.exe)?$')


def scoped(path,roots,*,existing=False):
    value=Path(path).absolute()
    if not any(value==Path(root).resolve() or value.is_relative_to(Path(root).resolve()) for root in roots):raise TerminalError('La ruta está fuera de las carpetas autorizadas.')
    for parent in (value,*value.parents):
        if parent.is_symlink() or getattr(parent,'is_junction',lambda:False)():raise TerminalError('No se admiten enlaces o junctions en rutas de terminal.')
    if value.resolve()!=value:raise TerminalError('La ruta debe ser local y canónica.')
    if existing and not value.exists():raise TerminalError('La ruta no existe.')
    return value


def repository_url(value):
    if not isinstance(value,str) or not re.fullmatch(r'https://github\.com/[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+(?:\.git)?/?',value):raise TerminalError('Usa la URL HTTPS exacta del repositorio GitHub, sin credenciales o parámetros.')
    return value.rstrip('/')


def child_environment(directory):
    allowed={'SYSTEMROOT','WINDIR','SYSTEMDRIVE','COMSPEC','PATH','PATHEXT','PROGRAMFILES','PROGRAMFILES(X86)','PROGRAMW6432','USERPROFILE','HOMEDRIVE','HOMEPATH','APPDATA','LOCALAPPDATA','TEMP','TMP','HOME','LANG','LC_ALL'}
    result={key:value for key,value in os.environ.items() if key.upper() in allowed}
    directory=Path(directory);directory.mkdir(parents=True,exist_ok=True)
    config=directory/'npm-user.conf'
    if not config.exists():config.write_text('',encoding='utf-8')
    result.update(GIT_TERMINAL_PROMPT='0',GCM_INTERACTIVE='never',NPM_CONFIG_USERCONFIG=str(config),NPM_CONFIG_AUDIT='false',NPM_CONFIG_FUND='false',NO_COLOR='1',CI='true')
    return result


def validate_program(binary,args):
    name=Path(binary).name
    if PROTECTED.fullmatch(name):raise TerminalError('Melodi no puede ejecutar esa herramienta del sistema.')
    if any(not isinstance(arg,str) or '\x00' in arg for arg in args):raise TerminalError('Argumentos de terminal no válidos.')
    if REGISTRY.search(' '.join([name,*args])):raise TerminalError('El registro está protegido: Melodi no puede consultarlo o modificarlo mediante comandos.','registry_forbidden')


def registry_guidance(route=None):
    return {'executable':False,'message':'Melodi no realiza cambios en el registro. Si decides hacerlos personalmente, son de alto riesgo y quedan bajo tu responsabilidad. Puedo explicar los pasos y sus efectos sin ejecutarlos.','route':route}
